#include "papinho_secure_transport.h"
#include "papinho_secure_transport_win32.h"
#include "backends/schannel/pst_backend_schannel.h"
#define _WINSOCK_DEPRECATED_NO_WARNINGS
#include <winsock2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int connect4(const char *address,unsigned short port,SOCKET *out){SOCKET s;struct sockaddr_in a;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(port);a.sin_addr.s_addr=inet_addr(address);s=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(s==INVALID_SOCKET)return 0;if(connect(s,(struct sockaddr*)&a,sizeof(a))==SOCKET_ERROR){closesocket(s);return 0;}*out=s;return 1;}
static int wait_step(pst_connection*c){PST_WAIT_RESULT w;PST_RESULT r;memset(&w,0,sizeof(w));r=pst_connection_wait(c,1000,&w);return r==PST_RESULT_OK&&!w.timed_out&&w.ready_interest!=0;}
int main(int argc,char**argv){const char payload[]="pst-phase5-public-runtime";WSADATA wd;SOCKET socket_value=INVALID_SOCKET;pst_trust*trust=NULL;pst_config*config=NULL;pst_runtime*runtime=NULL;pst_connection*connection=NULL;pst_transport*transport=NULL;PST_TRUST_SOURCE trust_source;PST_IDENTITY_CONFIG identity;PST_TLS_POLICY policy;PST_RUNTIME_OPTIONS options;PST_RUNTIME_INFO info;PST_IO_RESULT io;pst_u32 accepted,operation;PST_RESULT error,result;pst_size sent,received;char buffer[sizeof(payload)];int version,exchanges,i,steps,ok=0;const char*close_mode;if(argc!=6&&argc!=7){fprintf(stderr,"usage: address port hostname tls-version exchanges\n");return 2;}version=atoi(argv[4]);exchanges=atoi(argv[5]);close_mode=argc==7?argv[6]:"client";if((version!=12&&version!=13)||exchanges<1)return 2;if(WSAStartup(MAKEWORD(2,2),&wd)!=0)return 3;memset(&trust_source,0,sizeof(trust_source));trust_source.struct_size=sizeof(trust_source);trust_source.api_version=PST_API_VERSION;trust_source.kind=PST_TRUST_SOURCE_SYSTEM;if(pst_trust_create(&trust_source,&trust)!=PST_RESULT_OK)goto done;if(pst_config_create(&config)!=PST_RESULT_OK)goto done;memset(&identity,0,sizeof(identity));identity.struct_size=sizeof(identity);identity.api_version=PST_API_VERSION;identity.trust=trust;identity.expected_hostname=argv[3];identity.expected_hostname_size=strlen(argv[3]);identity.require_peer_authentication=1;if(pst_config_set_identity(config,&identity)!=PST_RESULT_OK)goto done;memset(&policy,0,sizeof(policy));policy.struct_size=sizeof(policy);policy.api_version=PST_API_VERSION;policy.minimum_version=(pst_u32)version;policy.maximum_version=(pst_u32)version;policy.early_data=PST_FEATURE_DISABLED;if(pst_config_set_tls_policy(config,&policy)!=PST_RESULT_OK||pst_config_freeze(config)!=PST_RESULT_OK)goto done;if(pst_backend_schannel_register()!=PST_RESULT_OK)goto done;memset(&options,0,sizeof(options));options.struct_size=sizeof(options);options.api_version=PST_API_VERSION;options.selection=PST_BACKEND_SELECTION_EXACT;options.exact_backend_id="schannel";options.required_capabilities=version==13?PST_CAP_TLS_1_3:PST_CAP_TLS_1_2;if(pst_runtime_create(&options,&runtime)!=PST_RESULT_OK)goto done;memset(&info,0,sizeof(info));info.struct_size=sizeof(info);info.api_version=PST_API_VERSION;if(pst_runtime_get_info(runtime,&info)!=PST_RESULT_OK)goto done;printf("BACKEND=%s CAPABILITIES=0x%08lx REQUESTED_TLS=0x%04x\n",info.backend_id,(unsigned long)info.capabilities,version==12?0x0303:0x0304);if(!connect4(argv[1],(unsigned short)atoi(argv[2]),&socket_value))goto done;if(pst_win32_socket_transport_create((pst_size)socket_value,&transport)!=PST_RESULT_OK)goto done;if(pst_connection_create(runtime,config,&connection)!=PST_RESULT_OK)goto done;accepted=0;if(pst_connection_attach(connection,transport,PST_OWNERSHIP_TRANSFERRED,&accepted)!=PST_RESULT_OK||!accepted)goto done;transport=NULL;socket_value=INVALID_SOCKET;for(steps=0;steps<200;steps++){result=pst_connection_handshake(connection,&operation,&error);printf("HANDSHAKE_STEP=%d RESULT=%ld OP=%lu ERROR=%ld\n",steps+1,(long)result,(unsigned long)operation,(long)error);if(result!=PST_RESULT_OK||operation==PST_OPERATION_FAILED)goto done;if(operation==PST_OPERATION_COMPLETE)break;if(!wait_step(connection))goto done;}if(steps==200)goto done;for(i=0;i<exchanges;i++){sent=0;while(sent<sizeof(payload)-1){memset(&io,0,sizeof(io));result=pst_connection_write(connection,payload+sent,sizeof(payload)-1-sent,&io);if(result!=PST_RESULT_OK||io.operation==PST_OPERATION_FAILED)goto done;sent+=io.bytes_transferred;if(sent<sizeof(payload)-1&&io.operation!=PST_OPERATION_COMPLETE&&!wait_step(connection))goto done;}received=0;while(received<sizeof(payload)-1){memset(&io,0,sizeof(io));result=pst_connection_read(connection,buffer+received,sizeof(payload)-1-received,&io);if(result!=PST_RESULT_OK||io.operation==PST_OPERATION_FAILED||io.operation==PST_OPERATION_CLOSED)goto done;received+=io.bytes_transferred;if(received<sizeof(payload)-1&&io.operation!=PST_OPERATION_COMPLETE&&!wait_step(connection))goto done;}if(received!=sizeof(payload)-1||memcmp(buffer,payload,sizeof(payload)-1))goto done;printf("EXCHANGE=%d WRITE=%lu READ=%lu CONTENT_MATCH=1\n",i+1,(unsigned long)sent,(unsigned long)received);}if(!strcmp(close_mode,"client")){for(steps=0;steps<20;steps++){result=pst_connection_shutdown(connection,&operation,&error);printf("SHUTDOWN_STEP=%d RESULT=%ld OP=%lu ERROR=%ld\n",steps+1,(long)result,(unsigned long)operation,(long)error);if(result!=PST_RESULT_OK||operation==PST_OPERATION_FAILED)goto done;if(operation==PST_OPERATION_COMPLETE)break;if(!wait_step(connection))goto done;}if(steps==20)goto done;printf("SCHANNEL_TLS=0x%04x EXCHANGES=%d WRITE=25 READ=25 CONTENT_MATCH=1 SHUTDOWN=COMPLETE PASS=1\n",version==12?0x0303:0x0304,exchanges);ok=1;}else{for(steps=0;steps<20;steps++){memset(&io,0,sizeof(io));result=pst_connection_read(connection,buffer,1,&io);if(result!=PST_RESULT_OK)goto done;if(io.operation==PST_OPERATION_CLOSED||io.operation==PST_OPERATION_FAILED)break;if(!wait_step(connection))goto done;}if(!strcmp(close_mode,"peer-clean"))ok=io.operation==PST_OPERATION_CLOSED&&io.close_kind==PST_CLOSE_CLEAN;else if(!strcmp(close_mode,"peer-abrupt"))ok=io.operation==PST_OPERATION_FAILED&&io.close_kind==PST_CLOSE_TRUNCATED&&io.error==PST_RESULT_TRUNCATED;printf("PEER_CLOSE_MODE=%s OP=%lu CLOSE_KIND=%lu ERROR=%ld PASS=%d\n",close_mode,(unsigned long)io.operation,(unsigned long)io.close_kind,(long)io.error,ok);}done:if(connection)pst_connection_release(connection);if(transport)pst_transport_release(transport);if(socket_value!=INVALID_SOCKET)closesocket(socket_value);if(runtime)pst_runtime_release(runtime);if(config)pst_config_release(config);if(trust)pst_trust_release(trust);pst_backend_registry_reset();WSACleanup();if(!ok)fprintf(stderr,"SCHANNEL_RUNTIME_INTEGRATION=FAIL\n");return ok?0:20;}